file.content:
      store?.openTerminal(targetID: targetID, tabID: tabID, notifID: notifID)
    }
  }
  completionHandler()
}

/// Confirm before quitting unless the user turned it off (`confirmOnQuit`, default on): quitting
/// tears down every terminal (and anything running in them) at once, with no undo. The dialog's
/// "Don't ask me again" checkbox turns the setting off (same key as the menu/Settings toggles).
/// `@MainActor` so the `NSAlert` (a main-actor AppKit type) call is clean — AppKit always invokes
/// this on the main thread. Closing a window doesn't quit the app, so this fires only on a quit.
@MainActor
func applicationShouldTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply {
  // UI-test fixture quits cleanly (no modal, no waiting) so XCUITest teardown never blocks. The
  // session still flushes here: this branch IS terminating, and a UI test that relaunches to check
  // what was restored must not race the coalescing timer (issue #46).
  if UITestFixture.isActive {
    SessionCoordinator.shared.flushAndFreeze()
    return .terminateNow
  }
  if Defaults[.confirmOnQuit] {
    let alert = NSAlert()
    alert.messageText = "Quit Workroom?"
    alert.informativeText =
      Defaults[.backgroundSessions]
      ? "Quitting leaves background terminals running. You can reattach them when you reopen Workroom."
      : "Quitting closes all terminals and stops any running processes."
    alert.addButton(withTitle: "Quit")
    alert.addButton(withTitle: "Cancel")
    alert.showsSuppressionButton = true
    alert.suppressionButton?.title = "Don't ask me again"
    let shouldQuit = alert.runModal() == .alertFirstButtonReturn
    // Ticking the box stops future confirmations — whether they Quit or Cancel, the checkbox
    // means "stop asking". Writes the same key the menu/Settings toggles bind to.
    if alert.suppressionButton?.state == .on {
      Defaults[.confirmOnQuit] = false
    }
    guard shouldQuit else { return .terminateCancel }
  }
  return stopRunCommandsThenTerminate(sender)
}

/// Ctrl-C any live run commands and let them exit before the process dies, so dev servers clean up
/// (release their port + pidfile) instead of being orphaned by the OS hangup on exit — a SIGHUP
/// that Puma ignores, surfacing as "A server is already running" on the next launch (issue #7).
/// Sends only key events — never frees a surface — so the no-mass-free-on-quit rationale in
/// `applicationWillTerminate` still holds. Bounded so a wedged server can't block the quit.
@MainActor
private func stopRunCommandsThenTerminate(_ sender: NSApplication) -> NSApplication.TerminateReply
{
  let registry = WindowRegistry.shared
  // Mark the app as terminating so a window's own close handler doesn't also prompt/stop (#70).
  registry.isTerminating = true
  // Write the session and stop writing (issue #46). Deliberately HERE and not at the top of
  // `applicationShouldTerminate`: that method can still return `.terminateCancel` at the confirm
  // dialog, and freezing above that guard would silently kill session saving for the rest of the
  // app's life after one cancelled ⌘Q. This point is past the guard and still before any window
  // closes — which is exactly what the freeze protects, since the document is rebuilt from the
  // live windows.
  SessionCoordinator.shared.flushAndFreeze()
  // With persistence off, the daemon does NOT get torn down by quitting (unlike an in-process
  // PTY, which the OS SIGHUPs when libghostty's memory is reclaimed — see the doc comment on
  // `applicationWillTerminate`): a daemon-held shell is a separate, independent process that
  // outlives Workroom on purpose. Nothing else ever kills it once the setting is off, so without
  // this every ordinary terminal's session would leak forever — silently contradicting the quit
  // alert's own promise ("stops any running processes") the moment the preference is off.
  let shouldStopPersistentSessions = !Defaults[.backgroundSessions]
  let group = DispatchGroup()
  if shouldStopPersistentSessions {
    group.enter()
    Task {
      await PersistentSessionService.shared.endAllSessions()
      group.leave()
    }
  }
  // A tab closed moments before quitting fires an unstructured kill Task (`closeTab`); wait for
  // it too, unconditionally — the persistence setting and run-command state above don't cover it,
  // so skipping this (the old early-return did, when neither applied) let that one session
  // outlive the quit despite the user having explicitly closed it.
  group.enter()
  Task {
    for store in registry.allStores { await store.terminals.awaitPendingCloseKills() }
    group.leave()
  }
  if registry.hasAnyLiveRunCommand {
    group.enter()
    // Stop every window's run commands, not just the focused one's.
    registry.gracefullyStopAllWindows(timeout: 5) { group.leave() }
  }
  group.notify(queue: .main) { sender.reply(toApplicationShouldTerminate: true) }
  return .terminateLater
}

